ALTER TABLE "PricingPlan" ADD COLUMN "category" VARCHAR(40) NOT NULL DEFAULT 'CARE_SEEKER', ADD COLUMN "tier" VARCHAR(40) NOT NULL DEFAULT '', ADD COLUMN "annualPricePence" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "trialMonths" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "featureRows" JSONB NOT NULL DEFAULT '[]', ADD COLUMN "entitlements" JSONB NOT NULL DEFAULT '{}';
