ALTER TABLE "Review" ADD COLUMN "response" VARCHAR(2000), ADD COLUMN "respondedAt" TIMESTAMP(3), ADD COLUMN "disputeReason" VARCHAR(1000);
UPDATE "PricingPlan" SET "active" = false;
